MAX_SEND_FRACTION  = 0.82   # default mid-game; adjusted per phase below

MAX_MOVES_PER_TURN         = 10
MAX_GROUP_ATTACKS_PER_TURN = 6   # increased for kill mode
MAX_SOURCES_PER_ATTACK     = 5
REINFORCE_MARGIN           = 3   # reduced — don't over-defend
ETA_SYNC_WINDOW            = 7.0
GROUP_OVERKILL_MARGIN      = 1   # tighter → save ships
MAX_EXTRA_OVERCOMMIT       = 5    # tighter overcommit cap

COMET_MIN_REMAIN_AFTER_CAPTURE = 25
COMET_MAX_SHIP_COST            = 18

MAX_TARGETS_CONSIDERED     = 40
CLOSE_TARGET_BONUS_RADIUS  = 35.0
CLOSE_TARGET_BONUS_WEIGHT  = 0.8
DISTANCE_PENALTY_WEIGHT    = 0.15   # reduced → prefer high-prod targets regardless of range

LOOKAHEAD_TURNS = 30

# Anti-stalemate tracker
_PROD_HISTORY   = []   # stores (step, my_prod_ratio) tuples
STALEMATE_TURNS = 60   # turns without ratio change → force aggression


# =============================================================================
# NN inference  (identical to v5 — pure numpy, no torch)
# =============================================================================
_NN_CACHE = {}

def _parse_nn_weights():
    global _NN_CACHE
    if _NN_CACHE or NN_WEIGHTS is None:
        return
    w = NN_WEIGHTS if isinstance(NN_WEIGHTS, dict) else json.loads(NN_WEIGHTS)
    _NN_CACHE = {
        "score_min": float(w["score_min"]),
        "score_max": float(w["score_max"]),
        "W0": np.array(w["W0"], dtype=np.float64),
        "b0": np.array(w["b0"], dtype=np.float64),
        "W1": np.array(w["W1"], dtype=np.float64),
        "b1": np.array(w["b1"], dtype=np.float64),
        "W2": np.array(w["W2"], dtype=np.float64),
        "b2": np.array(w["b2"], dtype=np.float64),
        "W3": np.array(w["W3"], dtype=np.float64),
        "b3": np.array(w["b3"], dtype=np.float64),
    }


def nn_forward(features):
    _parse_nn_weights()
    if not _NN_CACHE:
        return None
    x = np.array(features, dtype=np.float64)
    x = np.maximum(0.0, _NN_CACHE["W0"] @ x + _NN_CACHE["b0"])
    x = np.maximum(0.0, _NN_CACHE["W1"] @ x + _NN_CACHE["b1"])
    x = np.maximum(0.0, _NN_CACHE["W2"] @ x + _NN_CACHE["b2"])
    score_norm = float(np.asarray(_NN_CACHE["W3"] @ x + _NN_CACHE["b3"]).flat[0])
    smin = _NN_CACHE["score_min"]
    smax = _NN_CACHE["score_max"]
    return score_norm * (smax - smin) + smin


# =============================================================================
# Basic helpers  (unchanged from v5)
# =============================================================================
def get_obs_value(obs, key, default=None):
    if isinstance(obs, dict):
        return obs.get(key, default)
    return getattr(obs, key, default)


def get_field(obj, key, default=None):
    if isinstance(obj, dict):
        return obj.get(key, default)
    return getattr(obj, key, default)


def point_distance(x1, y1, x2, y2):
    return math.hypot(x1 - x2, y1 - y2)


def angle_to_xy(source, tx, ty):
    return math.atan2(ty - source[3], tx - source[2])


def fleet_speed(num_ships, max_speed=6.0):
    num_ships = max(1, int(num_ships))
    if num_ships <= 1:
        return 1.0
    value = (math.log(num_ships) / math.log(1000)) ** 1.5
    return 1.0 + (max_speed - 1.0) * value


def rotate_point(x, y, angle):
    dx = x - CENTER_X
    dy = y - CENTER_Y
    ca = math.cos(angle)
    sa = math.sin(angle)
    return (
        CENTER_X + dx * ca - dy * sa,
        CENTER_Y + dx * sa + dy * ca,
    )


# =============================================================================
# Orbit / comet prediction  (unchanged from v5)
# =============================================================================
def build_initial_map(initial_planets):
    result = {}
    if not initial_planets:
        return result
    for p in initial_planets:
        result[p[0]] = p
    return result


def is_orbiting_planet(p, initial_map):
    init = initial_map.get(p[0])
    if init is None:
        orbital_radius = point_distance(p[2], p[3], CENTER_X, CENTER_Y)
    else:
        orbital_radius = point_distance(init[2], init[3], CENTER_X, CENTER_Y)
    return orbital_radius + p[4] < 50.0


def build_comet_info(comets):
    info = {}
    if not comets:
        return info
    for group in comets:
        planet_ids = get_field(group, "planet_ids", [])
        paths     = get_field(group, "paths", [])
        path_index = int(get_field(group, "path_index", 0) or 0)
        for i, pid in enumerate(planet_ids):
            if i >= len(paths):
                continue
            path = paths[i]
            remaining = max(0, len(path) - path_index - 1)
            info[pid] = {"path": path, "index": path_index, "remaining": remaining}
    return info


def path_point_xy(point):
    if point is None:
        return None
    if len(point) >= 2:
        return float(point[0]), float(point[1])
    return None


def predict_position(p, dt, ctx):
    pid = p[0]
    if pid in ctx["comet_info"]:
        info = ctx["comet_info"][pid]
        idx  = int(info["index"] + max(0, round(dt)))
        path = info["path"]
        if 0 <= idx < len(path):
            xy = path_point_xy(path[idx])
            if xy is not None:
                return xy
        return p[2], p[3]
    if is_orbiting_planet(p, ctx["initial_map"]):
        angle = ctx["angular_velocity"] * dt
        return rotate_point(p[2], p[3], angle)
    return p[2], p[3]


def estimate_travel_to_target(source, target, ships, ctx, iterations=3):
    tx, ty = target[2], target[3]
    eta = point_distance(source[2], source[3], tx, ty) / fleet_speed(ships)
    for _ in range(iterations):
        tx, ty = predict_position(target, eta, ctx)
        eta = point_distance(source[2], source[3], tx, ty) / fleet_speed(ships)
    return eta, tx, ty


# =============================================================================
# Geometry  (unchanged from v5)
# =============================================================================
def segment_intersects_circle(x1, y1, x2, y2, cx, cy, radius):
    dx = x2 - x1
    dy = y2 - y1
    fx = x1 - cx
    fy = y1 - cy
    a  = dx * dx + dy * dy
    if a == 0:
        return point_distance(x1, y1, cx, cy) <= radius
    t = max(0.0, min(1.0, -((fx * dx) + (fy * dy)) / a))
    return point_distance(x1 + t * dx, y1 + t * dy, cx, cy) <= radius + 1.5


def path_hits_sun_xy(source, tx, ty):
    return segment_intersects_circle(
        source[2], source[3], tx, ty,
        CENTER_X, CENTER_Y, SUN_RADIUS + 0.5,
    )


def path_hits_other_planet_xy(source, target, tx, ty, planets):
    for p in planets:
        if p[0] == source[0] or p[0] == target[0]:
            continue
        if segment_intersects_circle(
            source[2], source[3], tx, ty,
            p[2], p[3], p[4] + 0.3,
        ):
            return True
    return False


def valid_source_to_target(source, target, ships, planets, ctx):
    eta, tx, ty = estimate_travel_to_target(source, target, ships, ctx)
    if target[0] in ctx["comet_info"]:
        remaining = ctx["comet_info"][target[0]]["remaining"]
        if remaining < eta + COMET_MIN_REMAIN_AFTER_CAPTURE:
            return False, eta, tx, ty
    if path_hits_sun_xy(source, tx, ty):
        return False, eta, tx, ty
    if path_hits_other_planet_xy(source, target, tx, ty, planets):
        return False, eta, tx, ty
    return True, eta, tx, ty


# =============================================================================
# Fleet inference  (unchanged from v5)
# =============================================================================
def ray_likely_hits_xy(fleet, tx, ty, radius, max_distance=None):
    fx, fy, angle = fleet[2], fleet[3], fleet[4]
    dir_x, dir_y  = math.cos(angle), math.sin(angle)
    vx, vy        = tx - fx, ty - fy
    projection    = vx * dir_x + vy * dir_y
    if projection < 0:
        return False
    if max_distance is not None and projection > max_distance:
        return False
    return point_distance(tx, ty, fx + projection * dir_x, fy + projection * dir_y) <= radius + 1.5


def estimate_fleet_eta_to_planet(fleet, planet, ctx):
    d   = point_distance(fleet[2], fleet[3], planet[2], planet[3])
    eta = d / fleet_speed(int(fleet[6]))
    tx, ty = predict_position(planet, eta, ctx)
    d2     = point_distance(fleet[2], fleet[3], tx, ty)
    eta2   = d2 / fleet_speed(int(fleet[6]))
    return eta2, tx, ty


def infer_incoming_fleets(planets, fleets, ctx):
    incoming = {}
    for f in fleets:
        owner = f[1]
        ships = int(f[6])
        best_pid, best_eta = None, 10 ** 9
        for p in planets:
            eta, tx, ty = estimate_fleet_eta_to_planet(f, p, ctx)
            max_dist = max(20.0, eta * fleet_speed(ships) + 3.0)
            if ray_likely_hits_xy(f, tx, ty, p[4], max_distance=max_dist) and eta < best_eta:
                best_eta = eta
                best_pid = p[0]
        if best_pid is not None:
            incoming.setdefault(best_pid, []).append(
                {"owner": owner, "ships": ships, "eta": best_eta}
            )
    return incoming


def incoming_ships_for(planet_id, incoming, owner_filter=None, not_owner=None,
                        eta_center=None, eta_window=10.0):
    total = 0
    for item in incoming.get(planet_id, []):
        if owner_filter is not None and item["owner"] != owner_filter:
            continue
        if not_owner is not None and item["owner"] == not_owner:
            continue
        if eta_center is not None and abs(item["eta"] - eta_center) > eta_window:
            continue
        total += int(item["ships"])
    return total


# =============================================================================
# NEW ▶  Game-phase & adaptive-reserve helpers
# =============================================================================
def get_game_phase(step, my_prod, enemy_prod):
    """Returns 'early', 'mid', or 'late'."""
    if step < 70:
        return "early"   # rush neutrals only
    if step > 350:
        return "late"    # all-in
    return "mid"


def get_send_fraction(phase, prod_ratio, is_stalemate):
    """
    Adaptive send fraction (= 1 - reserve fraction).
    prod_ratio = my_prod / max(1, enemy_prod)
    """
    if is_stalemate:
        return 0.92           # break stalemate → push hard
    if phase == "early":
        return 0.85           # expand fast, keep small cushion
    if phase == "late":
        return 0.95           # near end → almost all-in
    # mid-game: scale with dominance
    if prod_ratio >= 1.4:
        return 0.90           # winning → press advantage
    if prod_ratio >= 1.0:
        return 0.82
    if prod_ratio >= 0.7:
        return 0.75
    return 0.68               # losing → conservative


def detect_stalemate(step, my_prod_ratio):
    """
    Track my production share. If it hasn't changed by > 0.03 in
    STALEMATE_TURNS turns, we're in a stalemate.
    """
    global _PROD_HISTORY
    _PROD_HISTORY.append((step, my_prod_ratio))
    if len(_PROD_HISTORY) > STALEMATE_TURNS + 5:
        _PROD_HISTORY = _PROD_HISTORY[-(STALEMATE_TURNS + 5):]
    if len(_PROD_HISTORY) < STALEMATE_TURNS:
        return False
    old_ratio = _PROD_HISTORY[-STALEMATE_TURNS][1]
    return abs(my_prod_ratio - old_ratio) < 0.03


# =============================================================================
# Defense  (minor tweak: reserve uses dynamic fraction)
# =============================================================================
def available_ships_from_source(source, send_fraction=None):
    if send_fraction is None:
        send_fraction = MAX_SEND_FRACTION
    source_ships = int(source[5])
    reserve = max(MIN_RESERVE, int(source_ships * (1.0 - send_fraction)))
    return max(0, source_ships - reserve)


def detect_threats(my_planets, incoming, player):
    threats = []
    for p in my_planets:
        pid = p[0]
        enemy_items = [x for x in incoming.get(pid, []) if x["owner"] != player]
        if not enemy_items:
            continue
        enemy_items.sort(key=lambda x: x["eta"])
        min_eta = enemy_items[0]["eta"]
        enemy_ships = sum(x["ships"] for x in enemy_items if x["eta"] <= min_eta + 8.0)
        friendly_incoming = sum(
            x["ships"] for x in incoming.get(pid, [])
            if x["owner"] == player and x["eta"] <= min_eta + 8.0
        )
        future_garrison = int(p[5]) + int(p[6] * min_eta) + friendly_incoming
        deficit = enemy_ships - future_garrison + REINFORCE_MARGIN
        if deficit > 0:
            threats.append({
                "planet": p, "eta": min_eta,
                "deficit": int(deficit), "enemy_ships": int(enemy_ships),
            })
    threats.sort(key=lambda t: (t["eta"], -t["deficit"]))
    return threats


def apply_reinforcement(my_planets, planets, threats, budgets, moves, ctx,
                         incoming, player):
    used_sources = set()
    for threat in threats:
        if len(moves) >= MAX_MOVES_PER_TURN:
            break
        target = threat["planet"]
        need   = int(threat["deficit"])
        enemy_eta = threat["eta"]
        if need <= 0:
            continue
        candidates = []
        for source in my_planets:
            sid = source[0]
            if sid == target[0] or sid in used_sources or budgets.get(sid, 0) <= 0:
                continue
            if incoming_ships_for(sid, incoming, not_owner=player) > int(source[5]):
                continue
            probe_ships = min(budgets[sid], max(need, 5))
            ok, eta, tx, ty = valid_source_to_target(source, target, probe_ships, planets, ctx)
            if ok and eta <= enemy_eta + 4.0:
                candidates.append((eta, source, tx, ty))
        candidates.sort(key=lambda x: x[0])
        for eta, source, tx, ty in candidates:
            if len(moves) >= MAX_MOVES_PER_TURN or need <= 0:
                break
            sid  = source[0]
            send = min(budgets[sid], need)
            if send <= 0:
                continue
            ok2, eta2, tx2, ty2 = valid_source_to_target(source, target, send, planets, ctx)
            if not ok2:
                continue
            moves.append([int(sid), angle_to_xy(source, tx2, ty2), int(send)])
            budgets[sid] -= int(send)
            need -= int(send)
            used_sources.add(sid)
    return moves


# =============================================================================
# NEW ▶  Counter-attack: find enemy planets weakened by their own fleets
# =============================================================================
def find_exposed_enemy_planets(fleets, planets, player):
    """
    When an enemy planet recently sent ships, it has fewer ships than expected
    given its production rate.  We flag it as an exposed counter-attack target.

    Heuristic: for each enemy fleet still close to its likely source planet
    (< 18 units away), check if the source planet has fewer ships than
    8 * production (i.e. < 8 turns of buffer).  Those planets are exposed.
    Returns a set of planet-ids flagged as high-priority targets.
    """
    exposed = set()
    enemy_fleets = [f for f in fleets if f[1] != player]
    enemy_planets = {p[0]: p for p in planets if p[1] not in (-1, player)}

    for f in enemy_fleets:
        fx, fy = f[2], f[3]
        for pid, p in enemy_planets.items():
            dist = point_distance(fx, fy, p[2], p[3])
            if dist > 18.0:
                continue
            ships = int(p[5])
            prod  = max(1, int(p[6]))
            # Exposed if garrison < 8 turns of production
            if ships < prod * 8:
                exposed.add(pid)
    return exposed


# =============================================================================
# Feature extraction (identical to v5)
# =============================================================================
NUM_FEATURES = 13

def extract_features(source, target, eta, required, min_dist, step, planets,
                     player, ctx):
    owner       = target[1]
    target_ships = int(target[5])
    target_prod  = int(target[6])
    turns_left   = max(1, 500 - step)

    my_planets = [p for p in planets if p[1] == player]
    total_prod  = sum(int(p[6]) for p in planets)
    my_prod     = sum(int(p[6]) for p in my_planets)
    dist = point_distance(source[2], source[3], target[2], target[3])

    return [
        min(dist / 100.0, 1.0),
        min(eta / 80.0, 1.0),
        min(target_ships / 300.0, 1.0),
        min(target_prod / 10.0, 1.0),
        1.0 if owner == -1 else 0.0,
        1.0 if (owner != -1 and owner != player) else 0.0,
        min(required / 300.0, 1.0),
        min(available_ships_from_source(source) / 300.0, 1.0),
        step / 500.0,
        min(my_prod / max(1, total_prod), 1.0),
        min(len(my_planets) / max(1, len(planets)), 1.0),
        min(target_prod * min(turns_left, 120) / 1200.0, 1.0),
        min(min_dist / 100.0, 1.0),
    ]


# =============================================================================
# Required-ships estimator  (unchanged from v5)
# =============================================================================
def estimate_required_for_target(target, avg_eta, incoming, player, ctx):
    pid, owner       = target[0], target[1]
    target_ships, production = int(target[5]), int(target[6])
    base = target_ships + 1
    if owner == -1:
        future_growth = 0
        margin = 1                              # minimal — neutrals don't reinforce
    else:
        future_growth = int(production * avg_eta)
        margin = max(2, int(production * 1.2)) # tight vs v6's max(8, prod*3)
    if pid in ctx["comet_info"]:
        margin = 2
    my_incoming = incoming_ships_for(pid, incoming, owner_filter=player,
                                      eta_center=avg_eta, eta_window=12.0)
    enemy_extra = 0
    for item in incoming.get(pid, []):
        if item["owner"] == player or abs(item["eta"] - avg_eta) > 12.0:
            continue
        enemy_extra += (item["ships"] if item["owner"] == owner
                        else int(item["ships"] * 0.7))
    return max(0, int(base + future_growth + enemy_extra + margin - my_incoming))


# =============================================================================
# NEW ▶  Improved heuristic scorer (1v1 aware)
# =============================================================================
def heuristic_target_score(target, step, avg_eta, required, min_dist, ctx,
                            phase="mid", prod_ratio=1.0, is_exposed=False,
                            is_dominant=False):
    """
    ROI-based scorer (v7):
      score = prod_delta * effective_turns / cost  - distance_penalty
    prod_delta = prod for neutral, 2*prod for enemy (steal+deny).
    This naturally favours high-production cheap targets regardless of framing.
    """
    owner      = target[1]
    production = int(target[6])
    turns_left = max(1, 500 - step)

    # ── Comet guard (unchanged) ──
    if target[0] in ctx["comet_info"]:
        remaining    = ctx["comet_info"][target[0]]["remaining"]
        remain_after = remaining - avg_eta
        if remain_after < COMET_MIN_REMAIN_AFTER_CAPTURE or required > COMET_MAX_SHIP_COST:
            return -10 ** 9
        return remain_after * 0.3 - required * 1.0 - avg_eta * 0.5 + 10.0

    # ── Early rush: only capture neutrals ──
    if phase == "early" and owner != -1:
        return -10 ** 9   # completely block enemy attacks in rush phase

    if required <= 0:
        return -10 ** 9

    # Production delta over remaining game
    if owner == -1:
        prod_delta = production                # neutral: only gain
    else:
        prod_delta = production * 2.0          # enemy: gain mine + deny theirs
        if is_exposed:
            prod_delta *= 1.3                  # 30% bonus for weakened planet

    # Effective turns this planet produces for us
    effective_turns = min(turns_left - avg_eta, 400)
    if effective_turns <= 0:
        return -10 ** 9

    # ROI core = total production value / ships invested
    roi = (prod_delta * effective_turns) / required

    # Penalise distance (travel time = lost production time)
    dist_penalty = min_dist * DISTANCE_PENALTY_WEIGHT

    # Phase multipliers
    if phase == "late":
        if owner != -1:
            roi *= 1.8   # all-in on enemy late game
        roi *= 1.2       # general urgency
    elif phase == "mid":
        if prod_ratio >= 1.3 and owner != -1:
            roi *= 1.4   # press dominant advantage onto enemy

    return roi - dist_penalty


# =============================================================================
# Combined scorer (NN + heuristic fallback)  — same logic as v5
# =============================================================================
def compute_target_score(source, target, eta, required, min_dist, step, planets,
                         player, ctx, phase="mid", prod_ratio=1.0,
                         is_exposed=False, is_dominant=False):
    # v7: pure ROI heuristic — NN weights are corrupted, removed blending
    return heuristic_target_score(
        target, step, eta, required, min_dist, ctx,
        phase, prod_ratio, is_exposed, is_dominant,
    )


# =============================================================================
# NEW ▶  Better state_value (per-enemy weighting + late-game multiplier)
# =============================================================================
def state_value(planets, player, step, dt=LOOKAHEAD_TURNS):
    turns_left  = max(0, 500 - step - dt)
    late_mult   = 1.5 if step > 350 else 1.0   # late game: production counts more

    my_value    = 0.0
    enemy_value = 0.0

    enemies = list(set(p[1] for p in planets if p[1] not in (-1, player)))
    n_enemies = max(1, len(enemies))

    for p in planets:
        prod  = int(p[6])
        ships = int(p[5])
        future = prod * min(turns_left, 120) * late_mult + ships * 0.5
        if p[1] == player:
            my_value += future
        elif p[1] != -1:
            # In 1v1, there's only one enemy so this just normalises to 1
            enemy_value += future / n_enemies

    return my_value - enemy_value


def project_state_after_attacks(planets, attack_plans, player, step, ctx):
    pmap = {p[0]: list(p) for p in planets}
    for plan in attack_plans:
        target = plan["target"]
        eta    = plan["eta"]
        send   = plan["send"]
        tid    = target[0]
        if tid not in pmap:
            continue
        p             = pmap[tid]
        current_owner = p[1]
        current_ships = int(p[5])
        prod          = int(p[6])
        if current_owner == player:
            p[5] = current_ships + int(prod * eta) + send
        elif current_owner == -1:
            after = send - current_ships - 1
            if after > 0:
                p[1] = player
                p[5] = after
        else:
            future_garrison = current_ships + int(prod * eta)
            after = send - future_garrison
            if after > 0:
                p[1] = player
                p[5] = after
            else:
                p[5] = max(1, future_garrison - send)
        pmap[tid] = p
    return list(pmap.values())


# =============================================================================
# Attack / expansion planning  (identical to v5 except score call signature)
# =============================================================================
def build_source_candidates(target, my_planets, planets, budgets, ctx,
                             incoming, player):
    candidates = []
    for source in my_planets:
        sid       = source[0]
        available = budgets.get(sid, 0)
        if available <= 0:
            continue
        if incoming_ships_for(sid, incoming, not_owner=player) > int(source[5]):
            continue
        ok, eta, tx, ty = valid_source_to_target(source, target, available, planets, ctx)
        if not ok:
            continue
        candidates.append({
            "source":   source,
            "available": int(available),
            "eta_full":  eta,
            "tx": tx, "ty": ty,
            "dist": point_distance(source[2], source[3], tx, ty),
        })
    candidates.sort(key=lambda c: (c["eta_full"], c["dist"]))
    return candidates


def try_speed_up_to_eta(source, target, desired_eta, max_ships, ctx):
    max_ships = int(max_ships)
    if max_ships <= 1:
        return max_ships
    lo, hi, answer = 1, max_ships, max_ships
    while lo <= hi:
        mid = (lo + hi) // 2
        eta, _, _ = estimate_travel_to_target(source, target, mid, ctx)
        if eta <= desired_eta:
            answer = mid
            hi = mid - 1
        else:
            lo = mid + 1
    return max(1, min(answer, max_ships))


def allocate_group_ships(selected, target, required, planets, ctx):
    total_goal = int(required)
    if total_goal <= 0:
        return None
    selected   = sorted(selected, key=lambda c: (c["eta_full"], c["dist"]))
    total_cap  = sum(c["available"] for c in selected)
    if total_cap < total_goal:
        return None
    chosen, cap = [], 0
    for c in selected:
        chosen.append(c)
        cap += c["available"]
        if cap >= total_goal:
            break
    if not chosen:
        return None
    sync_eta   = max(c["eta_full"] for c in chosen)
    allocation = []
    remaining  = total_goal
    for c in chosen:
        if remaining <= 0:
            break
        source    = c["source"]
        available = c["available"]
        min_send  = try_speed_up_to_eta(source, target, sync_eta + ETA_SYNC_WINDOW,
                                         available, ctx)
        min_send  = min(min_send, available, remaining)
        if min_send <= 0:
            continue
        allocation.append({"source": source, "send": int(min_send), "available": available})
        remaining -= int(min_send)
    if not allocation:
        return None
    while remaining > 0:
        allocation.sort(
            key=lambda a: estimate_travel_to_target(a["source"], target, a["send"], ctx)[0],
            reverse=True,
        )
        changed = False
        for a in allocation:
            if remaining <= 0:
                break
            room = a["available"] - a["send"]
            if room <= 0:
                continue
            add = min(room, remaining)
            a["send"]  += int(add)
            remaining  -= int(add)
            changed     = True
        if not changed:
            break
    if remaining > 0:
        return None
    plan, etas, total_sent = [], [], 0
    for a in allocation:
        send = int(a["send"])
        if send <= 0:
            continue
        source = a["source"]
        ok, eta, tx, ty = valid_source_to_target(source, target, send, planets, ctx)
        if not ok:
            return None
        plan.append({"source": source, "send": send, "eta": eta, "tx": tx, "ty": ty})
        etas.append(eta)
        total_sent += send
    if not plan:
        return None
    if len(etas) > 1 and max(etas) - min(etas) > ETA_SYNC_WINDOW * 1.8:
        return None
    if total_sent > required + MAX_EXTRA_OVERCOMMIT:
        return None
    return plan


def make_group_plan(target, candidates, incoming, player, step, planets, ctx,
                    phase="mid", prod_ratio=1.0, exposed_pids=None,
                    is_dominant=False):
    if not candidates:
        return None
    if exposed_pids is None:
        exposed_pids = set()
    is_exposed   = target[0] in exposed_pids
    best_plan    = None
    best_score   = -10 ** 9

    for base in candidates:
        base_eta = base["eta_full"]
        cluster  = [
            c for c in candidates
            if abs(c["eta_full"] - base_eta) <= ETA_SYNC_WINDOW * 2.0
        ][:MAX_SOURCES_PER_ATTACK]
        if not cluster:
            continue
        avg_eta  = sum(c["eta_full"] for c in cluster) / len(cluster)
        required = estimate_required_for_target(target, avg_eta, incoming, player, ctx)
        if required <= 0:
            continue
        group_plan = allocate_group_ships(cluster, target, required, planets, ctx)
        if group_plan is None:
            continue
        actual_avg_eta = sum(x["eta"] for x in group_plan) / len(group_plan)
        total_sent     = sum(x["send"] for x in group_plan)
        min_dist       = min(
            point_distance(x["source"][2], x["source"][3], x["tx"], x["ty"])
            for x in group_plan
        )
        best_source = min(group_plan, key=lambda x: x["eta"])["source"]
        score = compute_target_score(
            best_source, target, actual_avg_eta, total_sent, min_dist,
            step, planets, player, ctx,
            phase=phase, prod_ratio=prod_ratio,
            is_exposed=is_exposed, is_dominant=is_dominant,
        )
        score -= len(group_plan) * 0.6
        if score > best_score:
            best_score = score
            best_plan  = {
                "target":     target,
                "moves":      group_plan,
                "score":      score,
                "total_sent": total_sent,
            }
    return best_plan


def choose_best_group_attack(my_planets, targets, planets, budgets, ctx,
                              incoming, player, step, used_targets,
                              phase="mid", prod_ratio=1.0, exposed_pids=None,
                              is_dominant=False):
    if exposed_pids is None:
        exposed_pids = set()
    best, best_score = None, -10 ** 9
    target_list = []
    for target in targets:
        if target[0] in used_targets:
            continue
        nearest_dist = min(
            point_distance(p[2], p[3], target[2], target[3])
            for p in my_planets
        )
        target_list.append((nearest_dist, target))
    target_list.sort(key=lambda x: x[0])
    for _, target in target_list[:MAX_TARGETS_CONSIDERED]:
        candidates = build_source_candidates(
            target, my_planets, planets, budgets, ctx, incoming, player
        )
        if not candidates:
            continue
        plan = make_group_plan(
            target, candidates, incoming, player, step, planets, ctx,
            phase=phase, prod_ratio=prod_ratio,
            exposed_pids=exposed_pids, is_dominant=is_dominant,
        )
        if plan is None:
            continue
        if plan["score"] > best_score:
            best_score = plan["score"]
            best       = plan
    return best


# =============================================================================
# 1-step lookahead  (unchanged logic, uses new state_value)
# =============================================================================
def evaluate_attack_set_with_lookahead(attack_plans_raw, planets, player, step, ctx):
    flat = []
    for plan in attack_plans_raw:
        for item in plan["moves"]:
            flat.append({"target": plan["target"], "eta": item["eta"], "send": item["send"]})
    projected = project_state_after_attacks(planets, flat, player, step, ctx)
    return state_value(projected, player, step)


# =============================================================================
# Final validation  (unchanged)
# =============================================================================
def validate_moves(moves, planets, player):
    owned = {p[0]: int(p[5]) for p in planets if p[1] == player}
    used  = {}
    safe  = []
    for source_id, angle, ships in moves:
        source_id = int(source_id)
        ships     = int(ships)
        if ships <= 0 or source_id not in owned:
            continue
        already   = used.get(source_id, 0)
        remaining = owned[source_id] - already
        send      = min(ships, remaining)
        if send > 0:
            safe.append([source_id, float(angle), int(send)])
            used[source_id] = already + send
    return safe


# =============================================================================
# Main agent  (v6 — fully rewritten flow)
# =============================================================================
def agent(obs):
    global TURN

    TURN += 1
    if TURN > 500:
        TURN = 1
    step = TURN

    player          = get_obs_value(obs, "player", 0)
    planets         = get_obs_value(obs, "planets", [])
    fleets          = get_obs_value(obs, "fleets", [])
    initial_planets = get_obs_value(obs, "initial_planets", planets)
    angular_velocity = float(get_obs_value(obs, "angular_velocity", 0.0) or 0.0)
    comets          = get_obs_value(obs, "comets", [])

    ctx = {
        "initial_map":     build_initial_map(initial_planets),
        "angular_velocity": angular_velocity,
        "comet_info":      build_comet_info(comets),
    }

    moves      = []
    my_planets = [p for p in planets if p[1] == player]
    targets    = [p for p in planets if p[1] != player]

    if not my_planets or not targets:
        return []

    # ── Economy snapshot ──────────────────────────────────────────────────────
    total_prod = max(1, sum(int(p[6]) for p in planets))
    my_prod    = sum(int(p[6]) for p in my_planets)
    enemy_prod = sum(int(p[6]) for p in planets if p[1] not in (-1, player))

    prod_ratio      = my_prod / max(1, enemy_prod)
    my_prod_share   = my_prod / total_prod
    phase           = get_game_phase(step, my_prod, enemy_prod)
    is_stalemate    = detect_stalemate(step, my_prod_share)
    is_dominant     = prod_ratio >= 1.3   # lower threshold → kill mode triggers sooner
    send_frac       = get_send_fraction(phase, prod_ratio, is_stalemate)

    # ── Fleet inference ───────────────────────────────────────────────────────
    incoming = infer_incoming_fleets(planets, fleets, ctx)

    # ── Build budgets with adaptive reserve ───────────────────────────────────
    budgets = {p[0]: available_ships_from_source(p, send_frac) for p in my_planets}

    # ── Counter-attack: mark exposed enemy planets ────────────────────────────
    exposed_pids = find_exposed_enemy_planets(fleets, planets, player)

    # ── 1. Defense ────────────────────────────────────────────────────────────
    threats = detect_threats(my_planets, incoming, player)
    apply_reinforcement(my_planets, planets, threats, budgets, moves, ctx,
                        incoming, player)

    # ── 2. Attack planning ───────────────────────────────────────────────────

    # ── KILL MODE: when dominant (prod_ratio >= 1.3), attack ALL enemy planets
    # simultaneously to prevent cross-reinforcement
    kill_mode = is_dominant or (phase == "late" and prod_ratio >= 1.0)
    n_attacks = 8 if kill_mode else MAX_GROUP_ATTACKS_PER_TURN

    used_targets = set()
    chosen_plans = []
    temp_budgets = dict(budgets)

    for _ in range(n_attacks):
        if len(moves) + len(chosen_plans) >= MAX_MOVES_PER_TURN:
            break
        plan = choose_best_group_attack(
            my_planets, targets, planets, temp_budgets, ctx, incoming,
            player, step, used_targets,
            phase=phase, prod_ratio=prod_ratio,
            exposed_pids=exposed_pids, is_dominant=is_dominant,
        )
        if plan is None:
            break
        # In kill mode, only accept plans that have positive ROI
        if kill_mode and plan["score"] < 0:
            break
        chosen_plans.append(plan)
        used_targets.add(plan["target"][0])
        for item in plan["moves"]:
            sid = item["source"][0]
            temp_budgets[sid] = max(0, temp_budgets.get(sid, 0) - item["send"])

    # ── Alternative beam: only in normal mode (kill mode is already greedy-all) ──
    if not kill_mode and len(chosen_plans) >= 2:
        best_val  = evaluate_attack_set_with_lookahead(chosen_plans, planets, player, step, ctx)
        best_set  = chosen_plans
        best_buds = temp_budgets

        skip_idx  = 0   # try skipping the top plan
        alt_used  = {chosen_plans[skip_idx]["target"][0]}
        alt_plans = []
        alt_buds  = dict(budgets)
        for _ in range(MAX_GROUP_ATTACKS_PER_TURN):
            plan = choose_best_group_attack(
                my_planets, targets, planets, alt_buds, ctx, incoming,
                player, step, alt_used,
                phase=phase, prod_ratio=prod_ratio,
                exposed_pids=exposed_pids, is_dominant=is_dominant,
            )
            if plan is None:
                break
            alt_plans.append(plan)
            alt_used.add(plan["target"][0])
            for item in plan["moves"]:
                sid = item["source"][0]
                alt_buds[sid] = max(0, alt_buds.get(sid, 0) - item["send"])

        if alt_plans:
            val = evaluate_attack_set_with_lookahead(alt_plans, planets, player, step, ctx)
            if val > best_val * 1.03:
                best_set  = alt_plans
                best_buds = alt_buds

        chosen_plans = best_set
        budgets      = best_buds
    else:
        budgets = temp_budgets

    # ── 3. Convert chosen plans to move list ─────────────────────────────────
    for plan in chosen_plans:
        for item in plan["moves"]:
            if len(moves) >= MAX_MOVES_PER_TURN:
                break
            source = item["source"]
            sid    = source[0]
            send   = int(item["send"])
            if send <= 0:
                continue
            angle = angle_to_xy(source, item["tx"], item["ty"])
            moves.append([int(sid), angle, int(send)])

    return validate_moves(moves, planets, player)
